import {
	useGenerateProjectGroupRevisionFromChatMutation,
	useCancelLatestInflightRevisionMutation,
	ProjectGroupRevisionAction,
	ChatUsageByOrganizationIdDocument,
	GenerationProvider,
	useCreateProjectGroupMutation,
	useCancelLatestInflightRevisionForThreadMutation,
	ProjectGroupRevisionStatus,
	GetProjectGroupRevisionsForChatDocument
} from '@/generated/graphql'
import { NEW_THREAD, useSetThreadId, useThreadId } from '../store/threadStore'
import { useRevisionSubStore } from './useSubscribeToRevisions'
import { generateClientId } from '@/utils/clientId'
import { setCommandForClientId } from '@/utils/chat-message-map'
import {
	addRevisionForChatToApolloCache,
	addThreadToApolloCache
} from '../utils/add-revision-for-chat'
import { useChatStore } from '../store/chatStore'
import { useCallback } from 'react'

export const useChatMutation = ({
	projectGroupId
}: {
	projectGroupId: string
}) => {
	const [createNewProjectGroup] = useCreateProjectGroupMutation({
		refetchQueries: ['GetProjectGroups']
	})
	const [generateProjectGroupRevisionFromChat, mutationResult] =
		useGenerateProjectGroupRevisionFromChatMutation()
	const [cancelLatestInflightRevision] =
		useCancelLatestInflightRevisionMutation()
	const [cancelLatestInflightRevisionForThread] =
		useCancelLatestInflightRevisionForThreadMutation()
	const threadId = useThreadId()
	const setSelectedThreadId = useSetThreadId()
	const subscribeToRevision = useRevisionSubStore(
		(state) => state.addRevisionId
	)
	const setIsGenerating = useChatStore((state) => state.setIsGenerating)
	const currentMessageId = useChatStore((state) => state.value.currentMessageId)
	const setCurrentMessageId = useChatStore((state) => state.setCurrentMessageId)
	const setChatState = useChatStore((state) => state.setChatState)
	const handleChat = useCallback(
		async ({
			chat,
			action,
			isThinkingMode,
			projectGroupId,
			organizationId,
			setProjectGroupId
		}: {
			chat: string
			action: ProjectGroupRevisionAction
			isThinkingMode: boolean
			projectGroupId: string
			organizationId: string
			setProjectGroupId: (projectGroupId: string) => void
		}) => {
			let currentProjectGroupId = projectGroupId
			if (!projectGroupId) {
				const { data } = await createNewProjectGroup({
					variables: {
						input: {
							organizationId
						}
					}
				})
				currentProjectGroupId = data?.createProjectGroup?.projectGroup?.id ?? ''
				setProjectGroupId(currentProjectGroupId)
			}

			if (!currentProjectGroupId) {
				setChatState('READY')
				throw new Error('Failed to create or get project group ID')
			}

			const clientId = generateClientId()
			setCommandForClientId({
				clientId,
				command: chat
			})
			const result = await generateProjectGroupRevisionFromChat({
				variables: {
					input: {
						projectGroupId: currentProjectGroupId,
						content: chat,
						viewingModuleId: null,
						action,
						useExtendedThinking: isThinkingMode,
						preferredGenerationProvider:
							GenerationProvider.ANTHROPIC_CLAUDE_SONNET_4,
						...(threadId === NEW_THREAD
							? { createNewThread: true }
							: { threadId })
					}
				},
				optimisticResponse: {
					__typename: 'Mutation',
					generateProjectGroupRevisionFromChat: {
						__typename: 'GenerateProjectGroupRevisionFromChatPayload',
						success: true,
						askForUserProfileInfo: false,
						projectGroupRevision: {
							__typename: 'ProjectGroupRevision',
							id: `optimistic-${clientId}`,
							action,
							status: ProjectGroupRevisionStatus.BUILDING,
							createdAt: new Date().toISOString(),
							previewURL: null,
							response: null,
							chat: {
								__typename: 'ProjectGroupChat',
								id: `optimistic-chat-${clientId}`,
								content: chat
							},
							thread:
								threadId === NEW_THREAD
									? {
											__typename: 'ProjectGroupRevisionThread',
											id: `optimistic-thread-${clientId}`,
											updatedAt: null,
											title: null,
											latestRevision: null
									  }
									: null
						}
					}
				},
				update: (cache, { data: updateData }) => {
					const revision =
						updateData?.generateProjectGroupRevisionFromChat
							.projectGroupRevision
					const newThread = revision?.thread
					if (threadId === NEW_THREAD && newThread) {
						setSelectedThreadId(newThread.id)
						addThreadToApolloCache({
							cache,
							projectGroupId: currentProjectGroupId,
							thread: newThread
						})
					}
					if (!revision) return
					subscribeToRevision({
						revisionId: revision.id,
						threadId: revision.thread?.id ?? null
					})
					addRevisionForChatToApolloCache({
						cache,
						projectGroupId: currentProjectGroupId,
						revision,
						clientId,
						threadId:
							threadId === NEW_THREAD
								? updateData.generateProjectGroupRevisionFromChat
										.projectGroupRevision.thread?.id ?? null
								: threadId,
						isNewProjectGroup: currentProjectGroupId !== projectGroupId
					})
				},
				refetchQueries: [
					{
						query: ChatUsageByOrganizationIdDocument,
						variables: {
							organizationId
						}
					}
				]
			})
			const revisionId =
				result.data?.generateProjectGroupRevisionFromChat.projectGroupRevision
					?.id
			if (!revisionId) {
				console.error('Failed to generate revision')
				throw new Error('Failed to generate revision')
			}

			return {
				revisionId,
				threadId:
					threadId === NEW_THREAD
						? result.data?.generateProjectGroupRevisionFromChat
								.projectGroupRevision?.thread?.id ?? null
						: threadId
			}
		},
		[
			setChatState,
			generateProjectGroupRevisionFromChat,
			threadId,
			createNewProjectGroup,
			subscribeToRevision,
			setSelectedThreadId
		]
	)

	const handleCancel = useCallback(async () => {
		if (typeof threadId === 'string' || threadId === null) {
			await cancelLatestInflightRevisionForThread({
				variables: {
					input: {
						projectGroupId,
						threadId
					}
				},
				refetchQueries: [GetProjectGroupRevisionsForChatDocument]
			})
		} else {
			await cancelLatestInflightRevision({
				variables: {
					input: {
						projectGroupId
					}
				},
				refetchQueries: [GetProjectGroupRevisionsForChatDocument]
			})
		}
		if (threadId !== NEW_THREAD) {
			setIsGenerating({ threadId, generating: false })
		}
		if (!currentMessageId) return
		setChatState('READY')
		setCurrentMessageId(null)
	}, [
		cancelLatestInflightRevisionForThread,
		cancelLatestInflightRevision,
		projectGroupId,
		threadId,
		setIsGenerating,
		currentMessageId,
		setChatState,
		setCurrentMessageId
	])

	return {
		handleChat,
		mutationResult,
		handleCancel
	}
}
